xinshengCustomCss:
/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ===== 日记 · 主题 CSS ===== */

@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400&display=swap');

/* ---------- 根容器 ---------- */
.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #333333;
  --xt-text-sub: #666666;
  --xt-text-muted: #999999;
  --xt-accent: #555555;
  --xt-accent-bg: rgba(85, 85, 85, 0.06);
  --xt-border: #eeeeee;
  --xt-radius: 18px;
  --xt-radius-sm: 9px;
  --xt-font: 'Noto Serif SC', "Songti SC", "STSong", Georgia, serif;
  --xt-anim-duration: 0.5s;
  --xt-anim-easing: cubic-bezier(0.25, 0.8, 0.35, 1);
  --xt-shadow-md: 0 6px 24px rgba(0, 0, 0, 0.04);
  --xt-glow-color: rgba(85, 85, 85, 0.15);

  position: relative;
  background: var(--xt-bg);
  box-shadow: var(--xt-shadow-md);
  padding-top: 46px !important;
  overflow: hidden;
}

.xt-root::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background-image: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.008) 0 1px,
    transparent 1px 3px
  );
}

/* ---------- 顶部栏 ---------- */
.xt-root::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 34px;
  z-index: 6;
  background: #fafafa;
  border-bottom: 1px solid #eeeeee;
  pointer-events: none;
}

/* ---------- 顶栏英文论文标题 ---------- */
.xt-text-reflectionTitleEN {
  position: absolute !important;
  top: -46px !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: 46px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  z-index: 10 !important;
  font-family: "Times New Roman", Georgia, "Songti SC", serif !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  letter-spacing: 2.5px !important;
  color: #555555 !important;
  white-space: nowrap !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  pointer-events: none !important;
  text-rendering: optimizeLegibility !important;
  font-variant: small-caps !important;
}

/* ---------- 内容层 ---------- */
.xt-content {
  position: relative;
  z-index: 20;
}

/* ---------- 左上角头像区 ---------- */
.xt-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 8px;
  margin: 0 0 16px 0;
  justify-content: flex-start;
}

.xt-header .xt-avatar {
  order: 0;
  flex: none;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid #ffffff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
  background-size: cover;
  background-position: center;
  filter: saturate(0.85) contrast(0.98);
}

.xt-header .xt-name {
  order: 1;
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.4px;
  color: #333333;
  line-height: 1.4;
}

.xt-header .xt-name::before {
  content: "@";
  margin-right: 2px;
  color: #999999;
  font-weight: 400;
}

.xt-header .xt-name::after {
  content: "骤雨初晴";
  display: block;
  font-size: 9px;
  color: #aaaaaa;
  font-weight: 400;
  letter-spacing: 1.2px;
  margin-top: 1px;
}

/* ---------- 头像点击热区（@toggle 4） ---------- */
.xt-action-4 {
  position: absolute !important;
  top: 6px !important;
  left: 12px !important;
  width: 52px !important;
  height: 52px !important;
  border-radius: 50% !important;
  z-index: 999999 !important;
  opacity: 0 !important;
  display: block !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  border: none !important;
  cursor: pointer !important;
  pointer-events: auto !important;
}

.xt-action-4::before,
.xt-action-4::after {
  display: none !important;
  content: none !important;
}

/* ---------- 顶部栏点击热区（@toggle 5） ---------- */
.xt-action-5 {
  position: absolute !important;
  top: -46px !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  height: 46px !important;
  z-index: 999999 !important;
  opacity: 0 !important;
  display: block !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  border: none !important;
  cursor: pointer !important;
  pointer-events: auto !important;
}

.xt-action-5::before,
.xt-action-5::after {
  display: none !important;
  content: none !important;
}

/* ---------- 日记正文 ---------- */
.xt-text-diaryBody {
  font-size: 12.5px;
  line-height: 2;
  letter-spacing: 0.5px;
  text-align: justify;
  color: #333333;
  margin-bottom: 8px;
  white-space: pre-wrap !important;
  word-break: break-word;
  overflow-wrap: anywhere;
  display: block !important;
  background: none !important;
  border: none !important;
  padding: 0 !important;
  box-shadow: none !important;
}

.xt-text-diaryBody > * {
  display: block;
  margin-bottom: 10px;
  white-space: pre-wrap;
}

/* ============================================================ */
/* 诗词弹窗（点击左上角头像）                                     */
/* ============================================================ */

.xt-row:has(> .xt-text-verseCN1) {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -46%) scale(0.9) !important;
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  z-index: 30 !important;

  display: flex !important;
  flex-direction: column !important;
  flex-wrap: nowrap !important;
  gap: 20px !important;
  align-items: center !important;
  justify-content: center !important;

  width: 86% !important;
  max-width: 480px !important;
  box-sizing: border-box !important;
  padding: 42px 40px 38px !important;
  margin: 0 !important;

  background: #ffffff !important;
  border: 1px solid #ececec !important;
  border-radius: 16px !important;
  box-shadow: 0 22px 60px rgba(0, 0, 0, 0.12), 0 6px 18px rgba(0, 0, 0, 0.05) !important;

  transition: opacity 0.38s ease,
              transform 0.55s cubic-bezier(0.34, 1.56, 0.64, 1),
              visibility 0.38s !important;
}

.xt-row:has(> .xt-text-verseCN1) > * {
  flex: 0 0 auto !important;
  width: 100% !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
}

#xt-t4:checked ~ .xt-content .xt-row:has(> .xt-text-verseCN1),
#xt-t4:checked ~ .xt-row:has(> .xt-text-verseCN1),
.xt-root:has(#xt-t4:checked) .xt-row:has(> .xt-text-verseCN1),
.xt-content:has(#xt-t4:checked) .xt-row:has(> .xt-text-verseCN1) {
  opacity: 1 !important;
  visibility: visible !important;
  pointer-events: auto !important;
  transform: translate(-50%, -50%) scale(1) !important;
}

/* ---------- verseCN1 ---------- */
.xt-text-verseCN1 {
  display: block !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 10px !important;
  letter-spacing: 3px !important;
  line-height: 1.8 !important;
  color: #111111 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  white-space: nowrap !important;
}

.xt-text-verseCN1::after {
  content: "" !important;
  display: block !important;
  width: 220px !important;
  height: 1.5px !important;
  background: #1a1a1a !important;
  margin: 18px auto 0 !important;
}

/* ---------- verseForeign ---------- */
.xt-text-verseForeign {
  display: block !important;
  width: 100% !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  margin: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  font-family: "Hiragino Mincho ProN", "Yu Mincho", "Noto Serif JP", "Songti SC", serif !important;
  font-size: 6px !important;
  letter-spacing: 2px !important;
  line-height: 1.6 !important;
  color: #111111 !important;
  text-align: center !important;
  white-space: nowrap !important;
}

.xt-text-verseForeign::before,
.xt-text-verseForeign::after {
  content: none !important;
  display: none !important;
}

/* ---------- verseCN2 ---------- */
.xt-text-verseCN2 {
  display: block !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 10px !important;
  letter-spacing: 3px !important;
  line-height: 1.8 !important;
  color: #111111 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  white-space: nowrap !important;
}

.xt-text-verseCN2::after {
  content: none !important;
  display: none !important;
}

/* ---------- 灰底块 ---------- */
.xt-row:has(> .xt-text-verseEN) {
  position: relative !important;
  display: block !important;
  width: 320px !important;
  max-width: 100% !important;
  height: 25px !important;
  padding: 0 !important;
  margin: 0 auto !important;
  background: #e8e8e8 !important;
  border: none !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

.xt-row:has(> .xt-text-verseEN) > * {
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  width: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  text-align: center !important;
  white-space: nowrap !important;
}

.xt-text-verseEN {
  z-index: 1 !important;
  transform: translate(-50%, -72%) !important;
  font-family: "Songti SC", "STSong", "SimSun", serif !important;
  font-size: 14px !important;
  line-height: 1 !important;
  letter-spacing: 1px !important;
  color: #888888 !important;
  font-style: normal !important;
}

.xt-text-verseEN_CN {
  z-index: 2 !important;
  transform: translate(-50%, -50%) !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 10px !important;
  line-height: 1 !important;
  letter-spacing: 4px !important;
  text-indent: 4px !important;
  color: #1a1a1a !important;
  font-weight: 500 !important;
  -webkit-text-stroke: 2px #ffffff !important;
  paint-order: stroke fill !important;
}

/* ---------- charName ---------- */
.xt-text-charName {
  display: block !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 10px !important;
  letter-spacing: 4px !important;
  color: #666666 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
}

.xt-text-charName::before,
.xt-text-charName::after {
  content: "|" !important;
  display: inline-block !important;
  margin: 0 10px !important;
  color: #666666 !important;
}

/* ============================================================ */
/* 日记详情视图（点击顶栏）                                       */
/* ============================================================ */

.xt-root:has(#xt-t5:checked) .xt-header,
.xt-root:has(#xt-t5:checked) .xt-text-diaryBody,
.xt-root:has(#xt-t5:checked) .xt-row:has(> .xt-text-verseCN1),
.xt-root:has(#xt-t5:checked) .xt-divider,
.xt-root:has(#xt-t5:checked) .xt-row:has(> .xt-action-1),
.xt-root:has(#xt-t5:checked) .xt-action-4 {
  display: none !important;
}

.xt-row:has(> .xt-text-reflectionTitle) {
  display: none !important;
  position: relative !important;
  flex-direction: column !important;
  flex-wrap: nowrap !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: 18px !important;
  width: 100% !important;
  box-sizing: border-box !important;
  padding: 34px 40px 52px !important;
  margin: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}

#xt-t5:checked ~ .xt-content .xt-row:has(> .xt-text-reflectionTitle),
#xt-t5:checked ~ .xt-row:has(> .xt-text-reflectionTitle),
.xt-root:has(#xt-t5:checked) .xt-row:has(> .xt-text-reflectionTitle),
.xt-content:has(#xt-t5:checked) .xt-row:has(> .xt-text-reflectionTitle) {
  display: flex !important;
}

.xt-row:has(> .xt-text-reflectionTitle) > * {
  position: static !important;
  flex: 0 0 auto !important;
  width: auto !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}

.xt-text-reflectionTitle {
  display: inline-block !important;
  text-align: center !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 19px !important;
  font-weight: 500 !important;
  letter-spacing: 6px !important;
  text-indent: 6px !important;
  color: #111111 !important;
  line-height: 1.4 !important;
  white-space: nowrap !important;
  width: auto !important;
  margin-top: 6px !important;
  text-rendering: optimizeLegibility !important;
}

.xt-text-reflectionTitle::after {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 6px !important;
  border: 1px solid #1a1a1a !important;
  background: transparent !important;
  box-sizing: border-box !important;
  margin: 16px auto 0 !important;
}

.xt-text-reflectionAuthor {
  display: block !important;
  width: 100% !important;
  text-align: center !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 12px !important;
  letter-spacing: 4px !important;
  color: #666666 !important;
  line-height: 1.4 !important;
  white-space: nowrap !important;
  margin-top: 2px !important;
}

.xt-text-reflectionAuthor::before {
  content: "著｜" !important;
  color: #666666 !important;
}

.xt-text-reflectionBody {
  display: block !important;
  width: 100% !important;
  text-align: justify !important;
  font-family: "Songti SC", "STSong", "SimSun", "Noto Serif SC", serif !important;
  font-size: 13px !important;
  letter-spacing: 1.5px !important;
  line-height: 2.2 !important;
  color: #333333 !important;
  white-space: normal !important;
  text-indent: 2em !important;
  margin: 0 !important;
}

/* ============================================================ */
/* 小纸条：点击「小纸条」按钮后铺开一张纸                          */
/* ============================================================ */

.xt-row:has(> .xt-text-noteA1) {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 52px !important;

  display: none !important;
  flex-direction: column !important;
  flex-wrap: nowrap !important;
  align-items: flex-start !important;
  justify-content: flex-start !important;
  gap: 6px !important;

  width: 100% !important;
  height: auto !important;
  min-height: 0 !important;
  box-sizing: border-box !important;

  padding: 30px 42px 44px 66px !important;
  margin: 0 !important;

  background-color: #ffffff !important;
  background-image:
    repeating-linear-gradient(
      to bottom,
      transparent 0,
      transparent 25px,
      rgba(140, 165, 200, 0.22) 25px,
      rgba(140, 165, 200, 0.22) 26px
    ) !important;
  background-position: 0 14px !important;

  border: none !important;
  border-radius: 0 0 18px 18px !important;
  box-shadow: none !important;

  overflow-y: auto !important;
  overflow-x: hidden !important;
  -webkit-overflow-scrolling: touch !important;
  z-index: 55 !important;
}

/* 左侧红装订线 */
.xt-row:has(> .xt-text-noteA1)::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  bottom: 0 !important;
  left: 48px !important;
  width: 1px !important;
  background: rgba(200, 110, 110, 0.28) !important;
  pointer-events: none !important;
}

/* 点击「小纸条」按钮后展开 */
#xt-t2:checked ~ .xt-content .xt-row:has(> .xt-text-noteA1),
#xt-t2:checked ~ .xt-row:has(> .xt-text-noteA1),
.xt-root:has(#xt-t2:checked) .xt-row:has(> .xt-text-noteA1),
.xt-content:has(#xt-t2:checked) .xt-row:has(> .xt-text-noteA1) {
  display: flex !important;
}

/* ---------- 每一段字迹 ---------- */
.xt-row:has(> .xt-text-noteA1) > * {
  position: static !important;
  flex: 0 0 auto !important;
  width: auto !important;
  max-width: 100% !important;
  box-sizing: border-box !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  font-size: 14px !important;
  line-height: 26px !important;
  letter-spacing: 1.2px !important;
  white-space: normal !important;
  text-align: left !important;
}

/* char 写的：楷体，深墨蓝，字迹稍重 */
.xt-text-noteA1,
.xt-text-noteA2,
.xt-text-noteA3,
.xt-text-noteA4,
.xt-text-noteA5,
.xt-text-noteA6 {
  font-family: "Kaiti SC", "STKaiti", "KaiTi", "楷体", "Noto Serif SC", serif !important;
  color: #23324a !important;
  font-weight: 500 !important;
  text-shadow: 0 0 0.35px rgba(35, 50, 74, 0.35) !important;
}

/* 对方写的：仿宋，灰墨，字迹稍轻，微微缩进 */
.xt-text-noteB1,
.xt-text-noteB2,
.xt-text-noteB3,
.xt-text-noteB4,
.xt-text-noteB5,
.xt-text-noteB6 {
  font-family: "STFangsong", "FangSong", "仿宋", "Noto Serif SC", serif !important;
  color: #6b7480 !important;
  font-weight: 400 !important;
  text-indent: 12px !important;
}

/* ---------- 右下角落款：谁和谁传的（视觉 5px，绝对定位） ---------- */
/* 选择器加前缀提高特殊性，覆盖上面的 position: static */
.xt-row:has(> .xt-text-noteA1) > .xt-text-noteFrom {
  display: block !important;
  position: absolute !important;
  right: 52px !important;
  bottom: 22px !important;
  width: auto !important;
  text-align: right !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: "Kaiti SC", "STKaiti", "KaiTi", "楷体", "Noto Serif SC", serif !important;
  font-size: 11px !important;
  line-height: 1 !important;
  letter-spacing: 0.6px !important;
  color: #9aa2ad !important;
  font-weight: 400 !important;
  text-shadow: none !important;
  white-space: nowrap !important;
  transform: scale(0.5) !important;
  transform-origin: right bottom !important;
  pointer-events: none !important;
  z-index: 2 !important;
}

/* ---------- 右下角落款：时间（视觉 4px，绝对定位） ---------- */
.xt-row:has(> .xt-text-noteA1) > .xt-text-noteTime {
  display: block !important;
  position: absolute !important;
  right: 52px !important;
  bottom: 10px !important;
  width: auto !important;
  text-align: right !important;
  margin: 0 !important;
  padding: 0 !important;
  font-family: "STFangsong", "FangSong", "仿宋", "Noto Serif SC", serif !important;
  font-size: 9px !important;
  line-height: 1 !important;
  letter-spacing: 0.5px !important;
  color: #b0b6bd !important;
  font-weight: 400 !important;
  text-shadow: none !important;
  white-space: nowrap !important;
  transform: scale(0.5) !important;
  transform-origin: right bottom !important;
  pointer-events: none !important;
  z-index: 2 !important;
}

/* 空字段自动隐藏 */
.xt-text-noteA1:empty,
.xt-text-noteA2:empty,
.xt-text-noteA3:empty,
.xt-text-noteA4:empty,
.xt-text-noteA5:empty,
.xt-text-noteA6:empty,
.xt-text-noteB1:empty,
.xt-text-noteB2:empty,
.xt-text-noteB3:empty,
.xt-text-noteB4:empty,
.xt-text-noteB5:empty,
.xt-text-noteB6:empty,
.xt-text-noteFrom:empty,
.xt-text-noteTime:empty {
  display: none !important;
}

/* ---------- 分隔线 ---------- */
.xt-divider {
  height: 1px !important;
  border: none !important;
  background: linear-gradient(90deg, transparent, #e5e5e5, transparent) !important;
  margin: 14px 0 4px !important;
}

/* ---------- 底部三按钮 ---------- */
.xt-action-1,
.xt-action-2,
.xt-action-3 {
  position: relative !important;
  z-index: 999 !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 8px 0 !important;
  background: transparent !important;
  border: none !important;
  border-radius: 8px;
  font-family: -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 10.5px;
  letter-spacing: 0.4px;
  color: #666666;
  cursor: pointer;
  user-select: none;
  transition: color 0.25s ease, background 0.25s ease;
}

.xt-action-1:hover,
.xt-action-2:hover,
