xinshengLayout:
# 顶部工具栏：名言滚动（样式里固定在 Menu 栏位置）
@marquee famousQuote

@spacer 8

@row 2
@card
  @image charImage
  @image userImage
@endcard

@card
  @text nickname
  @text signature
  @tags
    tag1
    tag2
    tag3
@endcard
@endrow

@spacer 16

@section DESCRIPTION
  description

@spacer 12

# 提问箱：用官方 @collapse 做成可点开的抽屉
@collapse "ANONYMOUS ASK BOX" 1
  @quote anonQuestion
  @text anonAnswer
@endcollapse

@spacer 12

# 聊天记录：左=Char，右=聊天对象（user以外的人），6个来回，不折叠
@card "CHAT LOG · 聊天记录"
  @text chatTitle
  @bubbles .stagger
    log1:left
    log2:right
    log3:left
    log4:right
    log5:left
    log6:right
    log7:left
    log8:right
    log9:left
    log10:right
    log11:left
    log12:right
@endcard

@spacer 12

# ===== 推特（iOS6 风）：Char 的秘密 =====
⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣@card
  @header charImage charName
  @text tweetHandle
  @text tweetText
  @text tweetTime
  @grid 2
    tweetRT:stat "转推"
    tweetFav:stat "喜欢"
@endcard

@spacer 14

# ===== 韩系论坛：帖子卡片与评论区分开绘制，避免评论被底栏或卡片样式遮挡 =====
@card
  @text forumBoard
  @text forumTitle
  @tags
    forumAuthor
    currentDate
    "조회"
    forumViews
    "추천"
    forumLikes
  @text forumBody
@endcard

@collapse "댓글 6" 0
  @text forumN1
  @text forumC1
  @text forumRN1
  @text forumR1
  @divider
  @text forumN2
  @text forumC2
  @divider
  @text forumN3
  @text forumC3
  @text forumRN2
  @text forumR2
  @divider
  @text forumN4
  @text forumC4
@endcollapse

@spacer 14

# ===== 小剧场：Char 和 user 的平行世界（每句台词前有署名，旁白穿插） =====
@card
  @text theaterTitle
  @text theaterWorld
  @text theaterScene
  @text theaterS1
  @text theaterL1
  @text theaterS2
  @text theaterL2
  @text theaterN2
  @text theaterS3
  @text theaterL3
  @text theaterS4
  @text theaterL4
  @text theaterN3
  @text theaterS5
  @text theaterL5
  @text theaterS6
  @text theaterL6
  @text theaterEnd
@endcard

@spacer 12

@section MY REVIEW
  review

