}

.xt-card { background: transparent !important; border: none !important; box-shadow: none !important; padding: 0 !important; margin: 0 !important; border-radius: 0 !important; }

/* ============ 分栏与错落照片墙 ============ */
.xt-row { 
    align-items: stretch !important; 
    margin-bottom: 16px !important;
}
.xt-row > *:first-child { 
    flex: 1.1; 
    display: flex; 
    flex-direction: column; 
    padding: 8px 12px 8px 0;
}
.xt-row > *:last-child { 
    flex: 2.2; 
