/* ============ 聊天记录：iOS 6 短信风（亚麻底 + 灰白/绿色气泡） ============ */
.xt-card-title {
    display: flex; align-items: center;
    font-size: 11px; font-weight: bold; color: #666;
    letter-spacing: 0.5px; margin-bottom: 8px;
    text-shadow: 0 1px 0 rgba(255,255,255,0.7);
}
.xt-card-title::before {
