@import url('https://cdn.jsdelivr.net/npm/@chinese-fonts/jhlst@3.0.0/dist/%E4%BA%AC%E8%8F%AF%E8%80%81%E5%AE%8B%E4%BD%93v2_002/result.css');

.xt-root {
    --xt-bg: #f7f7f5;
    --xt-text: #2a2622;
    --xt-text-sub: #5f5b56;
    --xt-text-muted: #9a968f;
    --xt-accent: #2a2622;
    --xt-border: #e2e1dc;
    --xt-radius: 8px;
    --xt-radius-sm: 4px;
    --xt-font: "KingHwa_OldSong", "Songti SC", serif;
    --my-avatar: url("https://s3.bmp.ovh/2026/09/28/ET4f2e7j.jpg");
    --author-avatar: url("https://s3.bmp.ovh/2026/09/28/d5IDLbDN.jpg");
    --reader1: url("https://s3.bmp.ovh/2026/09/28/WmlBKN6S.jpg");
    --reader2: url("https://s3.bmp.ovh/2026/09/28/IPjFsOHF.jpg");
    --reader3: url("https://s3.bmp.ovh/2026/09/28/WT1MuALL.jpg");
    --sea: url("https://s3.bmp.ovh/2026/09/28/5KTkAfQA.jpg");
    background: #f7f7f5;
    border-radius: 8px !important;
    padding: 0 !important;
    box-shadow: 0 6px 24px rgba(20, 30, 45, 0.14);
    max-height: 70vh;
    overflow-x: hidden;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
    scrollbar-width: none;
}

.xt-root::-webkit-scrollbar {
    display: none;
}

/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ ===== 翻页容器：三列 = 三页，横向吸附 ===== */
.xt-content {
    display: grid !important;
    grid-template-columns: repeat(3, 100%);
    grid-template-rows: repeat(6, auto) 1fr;
    padding: 0 !important;
    gap: 0 !important;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-x: contain;
    scrollbar-width: none;
}

.xt-content::-webkit-scrollbar {
    display: none;
}

.xt-content > * {
    min-width: 0;
    box-sizing: border-box;
}

.xt-row {
    margin: 0 !important;
    gap: 0 !important;
    border-radius: 0 !important;
    box-sizing: border-box;
}

/* 吸附点 */
.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)),
.xt-row:has(.xt-text-p1),
.xt-row:has(.xt-text-c1) {
    scroll-snap-align: start;
    scroll-snap-stop: always;
}

/* ===== 第一页：海面封面 ===== */
.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)) {
    grid-column: 1;
    grid-row: 1;
    position: relative;
    height: 260px;
    padding: 36px 32px !important;
    display: flex !important;
    flex-direction: row !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    background:
        linear-gradient(180deg, rgba(30,40,55,0.10) 0%, rgba(0,0,0,0) 45%, rgba(20,30,45,0.22) 100%),
        linear-gradient(rgba(120,130,140,0.14), rgba(120,130,140,0.14)),
        var(--sea) center 65% / cover no-repeat,
        linear-gradient(180deg,
            #2f5b93 0%,
            #4f7bb2 25%,
            #9fb6d3 46%,
            #c4cfdd 54%,
            #6f8fb8 58%,
            #5a7fab 72%,
            #34598a 100%);
}

.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)) > * {
    flex: none !important;
    width: auto !important;
    text-align: left !important;
}

.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)) .xt-text-bookTitle,
.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)) .xt-text-charName {
    writing-mode: vertical-rl;
    white-space: nowrap;
    background: none !important;
    border: none !important;
    padding: 0 !important;
    color: #fff !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-weight: 400 !important;
    text-shadow: 0 1px 3px rgba(0, 20, 45, 0.2);
}

.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)) .xt-text-bookTitle {
    margin: 0 !important;
    font-size: 40px;
    line-height: 1.05;
    letter-spacing: 8px;
}

.xt-row:has(.xt-text-charName):not(:has(.xt-text-c1)) .xt-text-charName {
    margin: 6px 0 0 22px !important;
    font-size: 14px;
    letter-spacing: 4px;
    opacity: 0.9;
}

.xt-content > .xt-text-innerVoice {
    grid-column: 1;
    grid-row: 2;
    align-self: start;
    margin: 36px 32px 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 18px;
    line-height: 2.05;
    letter-spacing: 0.5px;
    color: #2a2622;
}

.xt-content > .xt-text-chapter {
    grid-column: 1;
    grid-row: 3;
    align-self: start;
    margin: 16px 32px 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 15px;
    letter-spacing: 1px;
    color: #6f6b65;
}

.xt-content > .xt-text-chapter::before {
    content: "/";
    display: inline-block;
    margin-right: 8px;
    font-family: -apple-system, "PingFang SC", sans-serif;
    letter-spacing: 0;
}

.xt-divider {
    grid-column: 1;
    grid-row: 4;
    align-self: start;
    margin: 36px 32px 0 !important;
    height: 1px;
    border: none;
    background: #e2e1dc;
}

/* 签名行 */
.xt-row:has(.xt-text-date) {
    grid-column: 1;
    grid-row: 5;
    align-self: start;
    height: auto !important;
    margin: 22px 32px 0 !important;
    padding: 0 !important;
    background: none !important;
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    justify-content: flex-start !important;
    align-items: center !important;
}

.xt-row:has(.xt-text-date)::before {
    content: "";
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: var(--my-avatar) center / cover no-repeat;
    flex-shrink: 0;
    margin-right: 8px;
}

.xt-row:has(.xt-text-date) > * {
    flex: none !important;
    width: auto !important;
    text-align: left !important;
    margin: 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
    white-space: nowrap;
    color: #2a2622 !important;
    font-family: -apple-system, "PingFang SC", sans-serif;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0;
}

.xt-row:has(.xt-text-date) > .xt-text-userName {
    flex: 0 1 auto !important;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

.xt-row:has(.xt-text-date) > .xt-text-date::before {
    content: " · 摘录于 ";
    white-space: pre;
}

.xt-footer {
    grid-column: 1;
    grid-row: 6;
    align-self: start;
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    text-align: left !important;
    margin: 6px 32px 28px !important;
    padding: 0 !important;
    border: none !important;
    font-family: -apple-system, "PingFang SC", sans-serif;
    font-size: 13px;
    font-weight: 500;
    letter-spacing: 0.5px;
    color: #8a867f;
}

.xt-footer::after {
    content: "左滑翻页 ›";
    font-size: 11px;
    font-weight: 400;
    letter-spacing: 1px;
    color: #b3afa8;
}

/* ===== 第二页：阅读页 ===== */
.xt-row:has(.xt-text-p1) {
    grid-column: 2;
    grid-row: 1 / -1;
    position: relative;
    height: auto !important;
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    align-items: stretch !important;
    padding: 24px 30px 60px !important;
    background: #f7f7f5 !important;
}

.xt-row:has(.xt-text-p1) > * {
    flex: none !important;
    width: auto !important;
    text-align: left !important;
    margin: 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
}

.xt-row:has(.xt-text-p1) > .xt-text-bookTitle {
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 12px;
    letter-spacing: 2px;
    color: #a8a49d;
}

.xt-row:has(.xt-text-p1) > .xt-text-chapter {
    margin: 34px 0 22px !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 22px;
    line-height: 1.4;
    letter-spacing: 2px;
    color: #2a2622;
}

.xt-row:has(.xt-text-p1) > .xt-text-p1,
.xt-row:has(.xt-text-p1) > .xt-text-innerVoice,
.xt-row:has(.xt-text-p1) > .xt-text-p2 {
    margin-top: 12px !important;
    text-indent: 2em;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 17px;
    line-height: 1.95;
    letter-spacing: 0.5px;
    color: #2a2622;
}

.xt-row:has(.xt-text-p1) > .xt-text-p1 {
    margin-top: 0 !important;
}

.xt-row:has(.xt-text-p1) > .xt-text-innerVoice {
    text-decoration-line: underline;
    text-decoration-style: solid;
    text-decoration-color: #7d9cc0;
    text-decoration-thickness: 1.5px;
    text-underline-offset: 7px;
    text-decoration-skip-ink: none;
}

.xt-row:has(.xt-text-p1)::before,
.xt-row:has(.xt-text-p1)::after {
    position: absolute;
    bottom: 22px;
    font-family: -apple-system, "PingFang SC", sans-serif;
    font-size: 11px;
    letter-spacing: 1px;
    color: #b3afa8;
}

.xt-row:has(.xt-text-p1)::before {
    content: "微信读书";
    left: 30px;
}

.xt-row:has(.xt-text-p1)::after {
    content: "2 / 3";
    right: 30px;
}

/* ===== 第三页：名句 + 评论 + 书评 ===== */
.xt-row:has(.xt-text-c1) {
    grid-column: 3;
    grid-row: 1 / -1;
    height: auto !important;
    contain: size;
    display: flex !important;
    flex-direction: column !important;
    justify-content: flex-start !important;
    align-items: stretch !important;
    padding: 28px 28px 0 !important;
    background: #f7f7f5 !important;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
    scrollbar-width: none;
}

.xt-row:has(.xt-text-c1)::-webkit-scrollbar {
    display: none;
}

/* 页底留白 */
.xt-row:has(.xt-text-c1)::after {
    content: "";
    flex: none;
    height: 28px;
}

.xt-row:has(.xt-text-c1) > * {
    flex: none !important;
    width: auto !important;
    text-align: left !important;
    margin: 0 !important;
    padding: 0 !important;
    background: none !important;
    border: none !important;
}

/* 名句引用：直线 */
.xt-row:has(.xt-text-c1) > .xt-text-quote {
    padding-left: 12px !important;
    border-left: 2px solid #d9d6cf !important;
    border-radius: 0 !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 14px;
    line-height: 1.8;
    letter-spacing: 0.3px;
    color: #8a867f;
}

.xt-row:has(.xt-text-c1) > .xt-text-quoteFrom {
    margin: 6px 0 6px !important;
    text-align: right !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 12px;
    letter-spacing: 1px;
    color: #a8a49d;
}

.xt-row:has(.xt-text-c1) > .xt-text-quoteFrom::before {
    content: "——";
    margin-right: 4px;
    font-family: -apple-system, "PingFang SC", sans-serif;
    letter-spacing: 0;
}

/* 昵称行 + 头像 */
.xt-row:has(.xt-text-c1) > .xt-text-c1Name,
.xt-row:has(.xt-text-c1) > .xt-text-c2Name,
.xt-row:has(.xt-text-c1) > .xt-text-charName,
.xt-row:has(.xt-text-c1) > .xt-text-rName {
    position: relative;
    margin-top: 16px !important;
    padding: 16px 0 0 38px !important;
    border-top: 1px solid #e8e6e1 !important;
    font-family: -apple-system, "PingFang SC", sans-serif;
    font-size: 13px;
    font-weight: 500;
    line-height: 28px;
    letter-spacing: 0;
    color: #5f5b56;
}

.xt-row:has(.xt-text-c1) > .xt-text-c1Name::before,
.xt-row:has(.xt-text-c1) > .xt-text-c2Name::before,
.xt-row:has(.xt-text-c1) > .xt-text-charName::before,
.xt-row:has(.xt-text-c1) > .xt-text-rName::before {
    content: "";
    position: absolute;
    left: 0;
    top: 16px;
    width: 28px;
    height: 28px;
    border-radius: 50%;
}

.xt-row:has(.xt-text-c1) > .xt-text-c1Name::before {
    background: var(--reader1) center / cover no-repeat;
}

.xt-row:has(.xt-text-c1) > .xt-text-c2Name::before {
    background: var(--reader2) center / cover no-repeat;
}

.xt-row:has(.xt-text-c1) > .xt-text-rName::before {
    background: var(--reader3) center / cover no-repeat;
}

.xt-row:has(.xt-text-c1) > .xt-text-charName::before {
    background: var(--author-avatar) center / cover no-repeat;
}

.xt-row:has(.xt-text-c1) > .xt-text-charName::after {
    content: "作者";
    display: inline-block;
    margin-left: 6px;
    padding: 0 5px;
    border-radius: 3px;
    background: #2a2622;
    color: #f7f7f5;
    font-size: 10px;
    font-weight: 500;
    line-height: 16px;
    vertical-align: 1px;
}

/* 评论与书评正文 */
.xt-row:has(.xt-text-c1) > .xt-text-c1,
.xt-row:has(.xt-text-c1) > .xt-text-c2,
.xt-row:has(.xt-text-c1) > .xt-text-reply,
.xt-row:has(.xt-text-c1) > .xt-text-review {
    margin-top: 2px !important;
    padding-left: 38px !important;
    font-family: "KingHwa_OldSong", "Songti SC", serif;
    font-size: 15px;
    line-height: 1.8;
    letter-spacing: 0.3px;
    color: #2a2622;
}

/* ===== 书评区 ===== */
.xt-row:has(.xt-text-c1) > .xt-text-score {
    margin-top: 30px !important;
    padding-top: 22px !important;
    border-top: 6px solid #efeeea !important;
    font-family: -apple-system, "PingFang SC", sans-serif;
    font-size: 30px;
    font-weight: 600;
    line-height: 1.2;
    letter-spacing: 0;
    color: #2a2622;
}

.xt-row:has(.xt-text-c1) > .xt-text-score::before {
    content: "书评";
    display: block;
    margin-bottom: 14px;
    font-size: 17px;
    font-weight: 600;
    line-height: 1.4;
    color: #2a2622;
}

.xt-row:has(.xt-text-c1) > .xt-text-score::after {
    content: "推荐值";
    margin-left: 8px;
    font-size: 12px;
    font-weight: 400;
    letter-spacing: 1px;
    color: #9a968f;
}

.xt-row:has(.xt-text-c1) > .xt-text-level {
    align-self: flex-start;
    margin-top: 8px !important;
    padding: 2px 8px !important;
    border-radius: 3px;
    background: #e9eef4 !important;
    font-family: -apple-system, "PingFang SC", sans-serif;
    font-size: 12px;
    font-weight: 500;
    line-height: 18px;
    letter-spacing: 1px;
    color: #4f6f96;
}

.xt-row:has(.xt-text-c1) > .xt-text-rVerdict {
